def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row},
             key=lambda c: sum(row.count(c) for row in grid))
    out = [[bg] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and r + 1 < h:
                out[r + 1][c] = grid[r][c]
    return out
